insert into public.store_products(id,store_id,sku,name,short_description,description,category_slug,image_url,image_alt,price_vnd,stock_quantity,specifications,tags,is_published,is_featured) values
('51a00001-1a00-4a00-8a00-000000000001','8d51e759-874f-42c4-b137-48c3c18c7001','GM-KIT-FAMILY','Túi sơ cứu gia đình','Túi đựng vật tư sơ cứu gọn nhẹ, dễ cất giữ.','Túi sơ cứu dùng để sắp xếp vật tư chăm sóc ban đầu trong gia đình hoặc văn phòng. Thành phần bên trong cần được đơn vị bán xác nhận theo lô hàng.','first-aid-kits','/assets/products/first-aid-family-kit.svg','Túi sơ cứu gia đình màu đỏ, có ngăn kéo và quai xách',390000,35,'{"format":"túi xách","contents":"xác nhận theo lô hàng","storage":"nơi khô ráo"}','{túi sơ cứu,gia đình,văn phòng}',true,true),
('51a00001-1a00-4a00-8a00-000000000002','8d51e759-874f-42c4-b137-48c3c18c7001','GM-GAUZE-STERILE','Gạc y tế tiệt trùng','Gói gạc riêng lẻ phục vụ che phủ vết thương.','Gạc y tế đóng gói riêng. Kiểm tra nhãn, hạn dùng, tình trạng bao bì và hướng dẫn của nhà sản xuất trước khi sử dụng.','wound-care','/assets/products/sterile-gauze-pads.svg','Các gói gạc y tế màu trắng và xanh nhạt',45000,80,'{"pack_size":"theo quy cách trên bao bì","sterile":"kiểm tra nhãn lô hàng","expiry":"xem bao bì"}','{gạc,gạc tiệt trùng,vết thương}',true,true),
('51a00001-1a00-4a00-8a00-000000000003','8d51e759-874f-42c4-b137-48c3c18c7001','GM-COTTON-ROLL','Bông y tế cuộn','Bông mềm dạng cuộn, tiện bảo quản trong tủ thuốc.','Bông y tế dạng cuộn để dùng theo hướng dẫn trên nhãn sản phẩm. Không sử dụng thay cho vật tư chuyên dụng khi cần chăm sóc y tế.','wound-care','/assets/products/cotton-wool-roll.svg','Cuộn bông y tế trắng và một gói bông nhỏ',28000,100,'{"format":"cuộn","weight":"theo quy cách trên bao bì","storage":"khô, sạch"}','{bông y tế,bông cuộn,tủ thuốc}',true,false),
('51a00001-1a00-4a00-8a00-000000000004','8d51e759-874f-42c4-b137-48c3c18c7001','GM-BANDAGE-ROLL','Băng cuộn co giãn','Băng cuộn hỗ trợ cố định lớp gạc bên ngoài.','Băng cuộn co giãn dùng để giữ lớp băng phủ tại chỗ. Chọn kích thước phù hợp và làm theo hướng dẫn sử dụng của nhà sản xuất.','bandages','/assets/products/elastic-bandage-rolls.svg','Hai cuộn băng co giãn và cuộn băng dính y tế',35000,60,'{"format":"cuộn","size":"xác nhận theo lô hàng","material":"theo nhãn sản phẩm"}','{băng cuộn,băng co giãn,băng bó}',true,true),
('51a00001-1a00-4a00-8a00-000000000005','8d51e759-874f-42c4-b137-48c3c18c7001','GM-BANDAGE-STRIP','Miếng dán cá nhân','Miếng dán bảo vệ vết xước nhỏ, đóng gói theo hộp.','Miếng dán cá nhân dùng cho vết thương nhỏ theo hướng dẫn trên nhãn. Kiểm tra chất liệu, kích thước và hạn dùng của lô hàng.','bandages','/assets/products/adhesive-bandages.svg','Hộp miếng dán cá nhân với các miếng băng màu da',55000,50,'{"pack_size":"theo quy cách trên hộp","material":"xem nhãn sản phẩm","expiry":"xem bao bì"}','{miếng dán,băng cá nhân,vết xước}',true,false),
('51a00001-1a00-4a00-8a00-000000000006','8d51e759-874f-42c4-b137-48c3c18c7001','GM-GLOVES-NITRILE','Găng tay nitrile dùng một lần','Găng tay bảo hộ dùng trong thao tác sơ cứu.','Găng tay dùng một lần. Chọn kích cỡ phù hợp, kiểm tra chất liệu và thông tin dị ứng trên bao bì trước khi sử dụng.','ppe','/assets/products/nitrile-gloves.svg','Hộp găng tay và một chiếc găng nitrile màu xanh teal',125000,40,'{"material":"nitrile (xác nhận nhãn hàng)","size":"chọn theo lô","use":"dùng một lần"}','{găng tay,nitrile,bảo hộ}',true,true),
('51a00001-1a00-4a00-8a00-000000000007','8d51e759-874f-42c4-b137-48c3c18c7001','GM-CPR-BARRIER','Mặt nạ chắn CPR','Màng chắn bảo hộ dạng gói dùng khi hỗ trợ CPR.','Mặt nạ chắn dùng một lần hỗ trợ tạo lớp ngăn khi thực hành hoặc hỗ trợ hô hấp. Làm theo hướng dẫn nhà sản xuất và ưu tiên gọi 115 trong tình huống khẩn cấp.','cpr-barriers','/assets/products/cpr-face-shield.svg','Mặt nạ chắn CPR màu xanh trong một bao đựng',65000,45,'{"format":"gói đơn","use":"dùng một lần","expiry":"xem bao bì"}','{mặt nạ CPR,màng chắn,bảo hộ}',true,false),
('51a00001-1a00-4a00-8a00-000000000008','8d51e759-874f-42c4-b137-48c3c18c7001','GM-DRESSING-PAD','Băng gạc ép vô khuẩn','Miếng đệm băng bó đóng gói riêng.','Vật tư băng bó đóng gói riêng. Kiểm tra nhãn và hướng dẫn sản phẩm; chảy máu nghiêm trọng cần gọi 115 và làm theo hướng dẫn tổng đài.','wound-care','/assets/products/compression-dressing.svg','Gói băng gạc ép và miếng đệm màu trắng',72000,30,'{"format":"gói riêng","sterile":"kiểm tra nhãn lô hàng","expiry":"xem bao bì"}','{băng gạc,miếng đệm,sơ cứu}',true,false)
